};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    rdo_MKT_ID.setValue(scwin.gLdMktTp);

    /*
		if (gLdMktTp == '1' || gLdMktTp=='2' || gLdMktTp=='6' ) {	// 코넥스 시장 추가 20130520 LDJ
grd_Grid.setColumnProp("MKT_NM", "Show",false) ;
			showObj(panel_mkt, false);
		}
     */

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 유가일때만 초기 검색함
    // if (js_market == '1' ) {
    //    fn_CheckCond();
    // }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !사외이사--;
클릭-- > function() {
    // gDepCd =  getObjectValue(cmb_TeamList);
    // gEmpNo =  getObjectValue(cmb_EmpList);

    fn_Search();
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !사외이사--;
클릭-- > function() {
    const outDirNm = txb_OutDirNm.getValue();
    const url_list = "/OutDir.do?method=listOutDirDscl&inputMessageId=OUTDIRLIST_IN" + "&outputMessageId=OUTDIRLIST_OUT";
    const url_cond = "&ISUR_NM_CD=" + txb_isur_cd.getValue() + "&LD_MKT_TP=" + rdo_MKT_ID.getValue() + "&OUTDIR_NM=" + outDirNm + "&SCREN_ID=" + 'ULDSTF39000.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_OutDirlList.DataID = encodeURI(url_list + url_cond);
    dts_OutDirlList.reset();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_OutDirlList.getCellData(Number(obj), "ISUR_CD");
    scwin.gSeq = dts_OutDirlList.getCellData(Number(obj), "SEQ");
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "OUTDIR_NM") {
        const url = "/dsclmgt/ULDSTF39001.gfm";
        const winTitle = "사외이사 정보";
        // frame.CreateFrame("UDLSTF39001", url , winTitle ,200, 100, 500, 280, "window" , 0, 0, true);
        await $c.frame.CreateDialogFrame("UDLSTF39001", url, winTitle, 200, 100, 500, 280, "window");
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name dts_OutDirlList_OnLoadError
 * @description dts_OutDirlList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OutDirlList_OnLoadError = async function() {
    await $c.win.alert(dts_OutDirlList);
};

/**
 * @method
 * @name dts_OutDirlList_OnLoadCompleted
 * @description dts_OutDirlList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OutDirlList_OnLoadCompleted = async function(rowcount) {
    if (dts_OutDirlList.errorMsg) {
        await $c.win.alert(dts_OutDirlList.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
};

