/**
 * @method
 * @name cmb_TeamList_OnSelChange
 * @description cmb_TeamList 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = cmb_TeamList.ValueOfIndex("VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd === '') {
        cmb_EmpList.setValue('');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    // dts_emp.sort(); // W-Craft 주석처리

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description 부서코드에  해당하는 사원을 가져온다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd === "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") === "") {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF39000.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "사외이사 목록", type: "8"});
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description rdo_MKT_ID onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // fn_SetCtrlByMktId();

};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() === "") {
        txb_com_abbrv.setValue("");
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() === "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name btn_Upload_onclick
 * @description 「엑셀업로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Upload_onclick = async function() {
    clickId = "upload";
    const options = {
        id: "ULDSTF39003",
        title: "사외이사 일괄등록",
        type: "browserPopup",
        width: "590px",
        height: "270px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclmgt/ULDSTF39003.gfm", options);
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    clickId = "input";
    const options = {
        id: "ULDSTF39002",
        title: "사외이사 등록",
        type: "browserPopup",
        width: "600px",
        height: "300px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclmgt/ULDSTF39002.gfm", options);
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_outside(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name txb_OutDirNm_onkeydown
 * @description txb_OutDirNm 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_OutDirNm_onkeydown = function() {
    if (window.event.keyCode === "13") {
        fn_Search();
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    await scwin.setCode();
    // 사외이사 용
    $c.cm.fn_com_isur_outside(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
